#include <print>
#include <vector>

int main() {
    std::vector<int> v = {1, 3, 5, 7, 9, 11, 13, 15};
    int steps = 0;

    {   // 第一跑：target 取 8
        int target = 8;
        int lo = 0, hi = static_cast<int>(v.size()) - 1, pos = -1;
        while (lo <= hi) {
            ++steps;
            int mid = lo + (hi - lo) / 2;
            if (v[mid] == target) { pos = mid; break; }
            if (v[mid] < target) lo = mid + 1; else hi = mid - 1;
        }
        std::println("target={} 循环 {} 次 pos={} 收手 lo={} hi={}", target, steps, pos, lo, hi);
    }
    {   // 第二跑：target 取 1
        int target = 1;
        int lo = 0, hi = static_cast<int>(v.size()) - 1, pos = -1;
        steps = 0;
        while (lo <= hi) {
            ++steps;
            int mid = lo + (hi - lo) / 2;
            if (v[mid] == target) { pos = mid; break; }
            if (v[mid] < target) lo = mid + 1; else hi = mid - 1;
        }
        std::println("target={} 循环 {} 次 pos={}", target, steps, pos);
    }
    return 0;
}

