#include <print>
#include <vector>

int main() {
    std::vector<int> v = {1, 3, 5, 7, 9, 11, 13, 15};
    int target = 8;
    int pos = -1;
    for (size_t i = 0; i < v.size(); ++i)
        if (v[i] == target) { pos = static_cast<int>(i); break; }
    std::println("在下标 {}", pos);
    return 0;
}
